DROP TABLE IF EXISTS `achievements`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `achievements` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL COMMENT '成就名称',
  `description` text DEFAULT NULL COMMENT '成就描述',
  `icon` varchar(50) DEFAULT '?' COMMENT '图标',
  `category` enum('alchemy','fishing','mining','hunting','combat','social') NOT NULL COMMENT '分类',
  `requirement_type` enum('count','level','rare','legendary') NOT NULL DEFAULT 'count' COMMENT '达成类型',
  `requirement_value` int(11) NOT NULL COMMENT '达成条件数值',
  `points` int(11) NOT NULL DEFAULT 0 COMMENT '成就点数',
  `reward_silver` bigint(20) NOT NULL DEFAULT 0 COMMENT '银两奖励',
  `reward_exp` int(11) NOT NULL DEFAULT 0 COMMENT '经验奖励',
  `reward_item` varchar(50) DEFAULT NULL COMMENT '物品奖励',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_category` (`category`)
) ENGINE=InnoDB AUTO_INCREMENT=146 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='成就定义';
