(1,'多年不见，甚是想念','各位江湖朋友，好久不见！\n\n曾经的热血青春，如今的岁月静好。\n那些年我们一起追过的武侠梦，是否还在心中燃？\n\n笑傲江湖聊天室重新开放，愿各位在此重拾初心，再续江湖梦。\n\n- 注册即可赠送新手大礼包\n- 每日签到领福利\n- 加入门派切磋武艺\n- 寻找你的神仙眷侣\n\n多年不见，甚是想念。期待与你重逢在这个快意恩仇的武侠世界！','站长','2026-04-19 16:42:15',0);
