  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(10) unsigned DEFAULT NULL,
  `username` varchar(50) DEFAULT NULL,
  `ip_address` varchar(45) NOT NULL COMMENT 'IP 地址',
  `ip_type` enum('register','login','logout') NOT NULL DEFAULT 'login' COMMENT 'IP 类型',
  `user_agent` varchar(500) DEFAULT NULL COMMENT '浏览器信息',
  `login_status` enum('success','failed') DEFAULT 'success' COMMENT '登录状态',
  `reason` varchar(200) DEFAULT NULL COMMENT '失败原因',
  `country` varchar(50) DEFAULT NULL COMMENT '国家',
  `region` varchar(50) DEFAULT NULL COMMENT '省份',
  `city` varchar(50) DEFAULT NULL COMMENT '城市',
  `created_at` datetime NOT NULL DEFAULT current_timestamp() COMMENT '记录时间',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_ip_address` (`ip_address`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_username` (`username`),
  KEY `idx_login_status` (`login_status`),
  CONSTRAINT `user_ip_logs_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户 IP 记录历史表';
